# owner: platform
import unittest

from rosterkit.seating import seating_rows
from rosterkit.models import Student


def make_student(last, first):
    return Student("id-" + last, last, first, "A")


def sample_roster():
    return [
        make_student("Halloway", "Juno"),
        make_student("Dunmere", "Piet"),
        make_student("Abbott", "Cara")
    ]


class SeatingTests(unittest.TestCase):
    def test_sorted_and_grouped(self):
        rows = seating_rows(sample_roster(), 2)
        first = "Row 1: Abbott, Cara | Dunmere, Piet"
        self.assertEqual(rows[0], first)
        self.assertEqual(rows[1], "Row 2: Halloway, Juno")
        self.assertEqual(len(rows), 2)

    def test_single_row_when_seats_exceed_students(self):
        rows = seating_rows(sample_roster(), 10)
        self.assertEqual(len(rows), 1)

    def test_first_name_breaks_ties(self):
        pair = [
            make_student("Lund", "Zed"),
            make_student("lund", "Amy")
        ]
        rows = seating_rows(pair, 2)
        self.assertEqual(
            rows, ["Row 1: lund, Amy | Lund, Zed"]
        )

    def test_bad_seat_counts_raise(self):
        for seats in (0, -3):
            with self.assertRaises(ValueError):
                seating_rows(sample_roster(), seats)

    def test_no_students_raises(self):
        with self.assertRaises(ValueError):
            seating_rows([], 3)


if __name__ == "__main__":
    unittest.main()
